/** Patch only temporary compiled diagnostic copies. Never production source/build outputs. */
import {createHash} from 'node:crypto';
import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';
export function instrumentH0Json(source:string){if(source.includes('h0Original_'))throw Error('h0_instrument_anchor:already_instrumented');for(const name of ['canonicalOwnedJson','parseOwnedJson']){const needle='export function '+name+'(';if(source.split(needle).length!==2)throw Error('h0_instrument_anchor:'+name);source=source.replace(needle,'function h0Original_'+name+'(');source+=`\nexport function ${name}(...args){const probe=globalThis[Symbol.for('osv-mcp.h0.probe')];return probe?probe.sync('${name==='parseOwnedJson'?'json-decode':'json-canonical'}',()=>h0Original_${name}(...args)):h0Original_${name}(...args);}\n`;}return source;}
export async function instrumentH0Compiled(directory:string){const target=path.join(directory,'gradleOwnedJson.js');const before=await readFile(target,'utf8'),after=instrumentH0Json(before);await writeFile(target,after);const hash=(s:string)=>createHash('sha256').update(s).digest('hex');return {schema:'h0.compiled-json-instrumentation.v1',beforeSha256:hash(before),afterSha256:hash(after),wrappers:['canonicalOwnedJson','parseOwnedJson']};}
